+				t.Fatalf("adding an external agent changed project settings:\n%s", projectData)
+			}
+
+			data, err := os.ReadFile(EntireSettingsLocalFile)
+			if err != nil {
+				t.Fatalf("read target settings: %v", err)
+			}
